    -- Every published article must cite a source.
    ADD CONSTRAINT "knowledge_articles_published_has_source_check" CHECK ("status" <> 'PUBLISHED' OR "source_id" IS NOT NULL),
    ADD CONSTRAINT "knowledge_articles_source_section_not_blank_check" CHECK ("source_section" IS NULL OR btrim("source_section") <> ''),
    -- Facts that can change must carry review dates.
    ADD CONSTRAINT "knowledge_articles_time_sensitive_review_dates_check" CHECK (NOT "is_time_sensitive" OR ("last_reviewed_at" IS NOT NULL AND "next_review_at" IS NOT NULL)),
    ADD CONSTRAINT "knowledge_articles_review_order_check" CHECK ("last_reviewed_at" IS NULL OR "next_review_at" IS NULL OR "next_review_at" > "last_reviewed_at");

ALTER TABLE "knowledge_article_translations"
